// principalInjector returns a middleware that OVERWRITES the request's resolved
// Principal with the given role, regardless of what authMiddleware (which is NOT
// mounted on this test router) would have set. This is the AC-1 test-only
// synthetic principal: no resolver mints RoleClient today, so the
// client-authorization path of requireRole is only reachable by injection.
func principalInjector(role Role) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			ctx := context.WithValue(r.Context(), principalKey{}, Principal{Role: role})
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}
}

// gatingRouter builds a chi router that mounts the REAL /api/v1 route groups
// (via mountV1Routes — the same function New calls) behind a synthetic-principal
// injector instead of authMiddleware. It proves the role groups are wired so
// that a given role reaches the browse vs admin routes as AC-1 requires.
func gatingRouter(deps Deps, role Role) http.Handler {
	h := &app{deps: deps}
	r := chi.NewRouter()
	r.Use(principalInjector(role))
	r.Route("/api/v1", func(r chi.Router) { mountV1Routes(r, h) })
	return r
}

// TestNew_RoleGating is the S-routing + S-roles joint test (router side): the
// browse group (requireRole Admin+Client) admits both roles; the admin group
// (requireRole Admin) admits admin and denies client with 403 forbidden. The
// matrix exercises the REAL mountV1Routes wiring (the T08 deliverable) via a
// synthetic client principal; admin-reaches-all is additionally proven against
// the real New (with authMiddleware) for the authN-reachable case.
func TestNew_RoleGating(t *testing.T) {
	// wantByRole maps role -> expected status for that role hitting the route
	// through gatingRouter. The point is authZ (not the handler body): a 4xx
	// other than 403 still proves the route was reached (authZ passed), while
	// 403 means denied.
	cases := []struct {
		name       string
		method     string
		path       string
		body       string
		wantByRole map[Role]int
	}{
		// Browse group (admin+client) — authZ passes for both roles.
		{"browse_list_libraries", http.MethodGet, "/api/v1/libraries", "", map[Role]int{RoleAdmin: http.StatusOK, RoleClient: http.StatusOK}},
		{"browse_list_items", http.MethodGet, "/api/v1/items?library=1", "", map[Role]int{RoleAdmin: http.StatusOK, RoleClient: http.StatusOK}},
		{"browse_get_item", http.MethodGet, "/api/v1/items/anything", "", map[Role]int{RoleAdmin: http.StatusNotFound, RoleClient: http.StatusNotFound}},
		{"browse_get_library", http.MethodGet, "/api/v1/libraries/999", "", map[Role]int{RoleAdmin: http.StatusNotFound, RoleClient: http.StatusNotFound}},
		// Admin group (admin only) — admin reaches (handler-level non-403),
		// client denied (403 forbidden).
		{"admin_create_library", http.MethodPost, "/api/v1/libraries", `{"module_id":"x","root_path":"/x","display_name":"X"}`, map[Role]int{RoleAdmin: http.StatusCreated, RoleClient: http.StatusForbidden}},
		{"admin_scan_library", http.MethodPost, "/api/v1/libraries/1/scan", "", map[Role]int{RoleAdmin: http.StatusOK, RoleClient: http.StatusForbidden}},
		{"admin_put_item_parsers", http.MethodPut, "/api/v1/items/itm_x/parsers", `{"parsers":[]}`, map[Role]int{RoleAdmin: http.StatusNotFound, RoleClient: http.StatusForbidden}},
		{"admin_delete_item_parsers", http.MethodDelete, "/api/v1/items/itm_x/parsers", "", map[Role]int{RoleAdmin: http.StatusNotFound, RoleClient: http.StatusForbidden}},
		{"admin_status", http.MethodGet, "/api/v1/admin/status", "", map[Role]int{RoleAdmin: http.StatusServiceUnavailable, RoleClient: http.StatusForbidden}},
	}

	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			for _, role := range []Role{RoleAdmin, RoleClient} {
				role := role
				t.Run(string(role), func(t *testing.T) {
					st := openAPIStore(t)
					deps := Deps{
						AdminToken: adminToken,
						Store:      st,
						Scan: func(context.Context, int64) (scan.Result, error) {
							return scan.Result{LibraryID: 1}, nil
						},
					}
					h := gatingRouter(deps, role)
					resp := doRequest(t, h, tc.method, tc.path, tc.body, "no-authmw")
					defer resp.Body.Close()
					want := tc.wantByRole[role]
					if resp.StatusCode != want {
						t.Fatalf("role=%s %s %s: status = %d, want %d", role, tc.method, tc.path, resp.StatusCode, want)
					}
					if want == http.StatusForbidden {
						if eb := decodeError(t, resp); eb.Error.Code != "forbidden" {
							t.Fatalf("403 body error code = %q, want forbidden", eb.Error.Code)
						}
					}
				})
			}
		})
	}

	// Real New (with authMiddleware) — admin token reaches an admin-only route
	// and a browse route (authZ passes for admin in both groups). This covers
	// the production wiring for the authN-reachable case (the client path is
	// not authN-reachable today; the matrix above covers it via injection).
	t.Run("real_new_admin_token_passes_both_groups", func(t *testing.T) {
		st := openAPIStore(t)
		h := New(Deps{AdminToken: adminToken, Store: st, Scan: func(context.Context, int64) (scan.Result, error) {
			return scan.Result{}, nil
		}})
		browse := doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", adminToken)
		browse.Body.Close()
		if browse.StatusCode == http.StatusForbidden || browse.StatusCode == http.StatusUnauthorized {
			t.Fatalf("browse /libraries admin token: status = %d (authZ must pass for admin)", browse.StatusCode)
		}
		admin := doRequest(t, h, http.MethodGet, "/api/v1/admin/status", "", adminToken)
		admin.Body.Close()
		if admin.StatusCode == http.StatusForbidden || admin.StatusCode == http.StatusUnauthorized {
			t.Fatalf("admin /admin/status admin token: status = %d (authZ must pass for admin)", admin.StatusCode)
		}
	})
}
